17	package org.apache.kafka.server;
18	
19	import org.apache.kafka.clients.ClientResponse;
20	import org.apache.kafka.common.Uuid;
21	import org.apache.kafka.common.message.BrokerHeartbeatRequestData;
22	import org.apache.kafka.common.message.BrokerHeartbeatResponseData;
23	import org.apache.kafka.common.message.BrokerRegistrationRequestData;
24	import org.apache.kafka.common.message.BrokerRegistrationRequestData.ListenerCollection;
25	import org.apache.kafka.common.protocol.Errors;
26	import org.apache.kafka.common.requests.BrokerHeartbeatRequest;
27	import org.apache.kafka.common.requests.BrokerHeartbeatResponse;
28	import org.apache.kafka.common.requests.BrokerRegistrationRequest;
29	import org.apache.kafka.common.requests.BrokerRegistrationResponse;
30	import org.apache.kafka.common.utils.LogContext;
31	import org.apache.kafka.common.utils.Time;
32	import org.apache.kafka.metadata.BrokerState;
33	import org.apache.kafka.metadata.VersionRange;
34	import org.apache.kafka.queue.EventQueue;
35	import org.apache.kafka.queue.KafkaEventQueue;
36	import org.apache.kafka.server.common.ControllerRequestCompletionHandler;
37	import org.apache.kafka.server.common.NodeToControllerChannelManager;
38	import org.apache.kafka.server.config.AbstractKafkaConfig;
39	
40	import org.slf4j.Logger;
41	
42	import java.util.ArrayList;
43	import java.util.HashMap;
44	import java.util.List;
45	import java.util.Map;
46	import java.util.Optional;
47	import java.util.OptionalLong;
48	import java.util.Set;
49	import java.util.concurrent.CompletableFuture;
50	import java.util.function.Supplier;
51	
52	import static java.util.concurrent.TimeUnit.MILLISECONDS;
53	import static java.util.concurrent.TimeUnit.NANOSECONDS;
54	
55	/**
56	 * The broker lifecycle manager owns the broker state.
57	 *
58	 * Its inputs are messages passed in from other parts of the broker and from the
59	 * controller: requests to start up, or shut down, for example. Its output are the broker
60	 * state and various futures that can be used to wait for broker state transitions to
61	 * occur.
62	 *
63	 * The lifecycle manager handles registering the broker with the controller, as described
64	 * in KIP-631. After registration is complete, it handles sending periodic broker
65	 * heartbeats and processing the responses.
66	 *
67	 * This code uses an event queue paradigm. Modifications get translated into events, which
68	 * are placed on the queue to be processed sequentially. As described in the JavaDoc for
69	 * each variable, most mutable state can be accessed only from that event queue thread.
70	 * In some cases we expose a volatile variable which can be read from any thread, but only
71	 * written from the event queue thread.
72	 */
73	public class BrokerLifecycleManager {
74	
75	    private final Logger logger;
76	    private final KafkaEventQueue eventQueue;
77	    private final AbstractKafkaConfig config;
78	    private final Time time;
79	    private final Set<Uuid> logDirs;
80	    private final Runnable shutdownHook;
81	
82	    /**
83	     * The broker id.
84	     */
85	    private final int nodeId;
86	
87	    /**
88	     * The broker rack, or null if there is no configured rack.
89	     */
90	    private final Optional<String> rack;
91	
92	    /**
93	     * How long to wait for registration to succeed before failing the startup process.
94	     */
95	    private final long initialTimeoutNs;
96	
97	    /**
98	     * The broker incarnation ID.  This ID uniquely identifies each time we start the broker
99	     */
100	    private final Uuid incarnationId = Uuid.randomUuid();
101	
102	    /**
103	     * A future which is completed just as soon as the broker has caught up with the latest
104	     * metadata offset for the first time.
105	     */
106	    private final CompletableFuture<Void> initialCatchUpFuture = new CompletableFuture<>();
107	
108	    /**
109	     * A future which is completed when the broker is unfenced for the first time.
110	     */
111	    private final CompletableFuture<Void> initialUnfenceFuture = new CompletableFuture<>();
112	
113	    /**
114	     * A future which is completed when controlled shutdown is done.
115	     */
116	    private final CompletableFuture<Void> controlledShutdownFuture = new CompletableFuture<>();
117	
118	    /**
119	     * The broker epoch, or -1 if the broker has not yet registered.  This variable can only
120	     * be written from the event queue thread.
121	     */
122	    private volatile long brokerEpoch = -1L;
123	
124	    /**
125	     * The current broker state.  This variable can only be written from the event queue
126	     * thread.
127	     */
128	    private volatile BrokerState state = BrokerState.NOT_RUNNING;
129	
130	    /**
131	     * A thread-safe callback function which gives this manager the current highest metadata
132	     * offset.  This variable can only be read or written from the event queue thread.
133	     */
134	    private Supplier<Long> highestMetadataOffsetProvider;
135	
136	    /**
137	     * True only if we are ready to unfence the broker.  This variable can only be read or
138	     * written from the event queue thread.
139	     */
140	    private boolean readyToUnfence = false;
141	
142	    /**
143	     * Map of accumulated offline directories. The value is true if the directory has been successfully communicated
144	     * to the Controller.
145	     * This variable can only be read or written from the event queue thread.
146	     */
147	    private Map<Uuid, Boolean> offlineDirs = new HashMap<>();
148	
149	    /**
150	     * True if we sent an event queue to the active controller requesting controlled
151	     * shutdown.  This variable can only be read or written from the event queue thread.
152	     */
153	    private boolean gotControlledShutdownResponse = false;
154	
155	    /**
156	     * Whether this broker is registered with the controller quorum.
157	     * This variable can only be read or written from the event queue thread.
158	     */
159	    private boolean registered = false;
160	
161	    /**
162	     * True if a request has been sent and a response or timeout has not yet been processed.
163	     * This variable can only be read or written from the event queue thread.
164	     */
165	    private boolean communicationInFlight = false;
166	
167	    /**
168	     * True if we should schedule the next communication immediately. This is used to delay
169	     * an immediate scheduling of a communication event if one is already in flight.
170	     * This variable can only be read or written from the event queue thread.
171	     */
172	    private boolean nextSchedulingShouldBeImmediate = false;
173	
174	    /**
175	     * True if the initial registration succeeded.  This variable can only be read or
176	     * written from the event queue thread.
177	     */
178	    private boolean initialRegistrationSucceeded = false;
179	
180	    /**
181	     * The cluster ID, or null if this manager has not been started yet.  This variable can
182	     * only be read or written from the event queue thread.
183	     */
184	    private String clusterId;
185	
186	    /**
187	     * The listeners which this broker advertises.  This variable can only be read or
188	     * written from the event queue thread.
189	     */
190	    private ListenerCollection advertisedListeners;
191	
192	    /**
193	     * The features supported by this broker.  This variable can only be read or written
194	     * from the event queue thread.
195	     */
196	    private Map<String, VersionRange> supportedFeatures;
197	
198	    /**
199	     * The channel manager, or null if this manager has not been started yet.  This variable
200	     * can only be read or written from the event queue thread.
201	     */
202	    private NodeToControllerChannelManager channelManager;
203	
204	    /**
205	     * The broker epoch from the previous run, or empty if the epoch is not found.
206	     */
207	    private volatile OptionalLong previousBrokerEpoch = OptionalLong.empty();
208	
209	    public BrokerLifecycleManager(
210	            AbstractKafkaConfig config,
211	            Time time,
212	            String threadNamePrefix,
213	            Set<Uuid> logDirs) {
214	        this(config, time, threadNamePrefix, logDirs, () -> { });
215	    }
216	
217	    public BrokerLifecycleManager(
218	            AbstractKafkaConfig config,
219	            Time time,
220	            String threadNamePrefix,
221	            Set<Uuid> logDirs,
222	            Runnable shutdownHook) {
223	        this.config = config;
224	        this.time = time;
225	        this.logDirs = logDirs;
226	        this.shutdownHook = shutdownHook;
227	        LogContext logContext = new LogContext("[BrokerLifecycleManager id=" + this.config.nodeId() + "] ");
228	        this.logger = logContext.logger(BrokerLifecycleManager.class);
229	        this.nodeId = config.nodeId();
230	        this.rack = config.rack();
231	        this.initialTimeoutNs = MILLISECONDS.toNanos(config.initialRegistrationTimeoutMs());
232	        this.eventQueue = new KafkaEventQueue(
233	                time,
234	                logContext,
235	                threadNamePrefix + "lifecycle-manager-",
236	                new ShutdownEvent());
237	    }
238	
239	    /**
240	     * Start the BrokerLifecycleManager.
241	     *
242	     * @param highestMetadataOffsetProvider Provides the current highest metadata offset.
243	     * @param channelManager                The NodeToControllerChannelManager to use.
244	     * @param clusterId                     The cluster ID.
245	     * @param advertisedListeners           The advertised listeners for this broker.
246	     * @param supportedFeatures             The features for this broker.
247	     * @param previousBrokerEpoch           The broker epoch before the reboot.
248	     */
249	    public void start(Supplier<Long> highestMetadataOffsetProvider,
250	               NodeToControllerChannelManager channelManager,
251	               String clusterId,
252	               ListenerCollection advertisedListeners,
253	               Map<String, VersionRange> supportedFeatures,
254	               OptionalLong previousBrokerEpoch) {
255	        this.previousBrokerEpoch = previousBrokerEpoch;
256	        eventQueue.append(new StartupEvent(highestMetadataOffsetProvider,
257	                channelManager, clusterId, advertisedListeners, supportedFeatures));
258	    }
259	
260	    public CompletableFuture<Void> setReadyToUnfence() {
261	        eventQueue.append(new SetReadyToUnfenceEvent());
262	        return initialUnfenceFuture;
263	    }
264	
265	    /**
266	     * Propagate directory failures to the controller.
267	     *
268	     * @param directory The ID for the directory that failed.
269	     */
270	    public void propagateDirectoryFailure(Uuid directory, long timeout) {
271	        eventQueue.append(new OfflineDirEvent(directory));
272	        // If we can't communicate the offline directory to the controller, we should shut down.
273	        eventQueue.scheduleDeferred("offlineDirFailure",
274	                new EventQueue.DeadlineFunction(time.nanoseconds() + MILLISECONDS.toNanos(timeout)),
275	                new OfflineDirBrokerFailureEvent(directory));
276	    }
277	
278	    public void resendBrokerRegistration() {
279	        eventQueue.append(new ResendBrokerRegistrationEvent());
280	    }
281	
282	    private class ResendBrokerRegistrationEvent implements EventQueue.Event {
283	        @Override
284	        public void run() {
285	            registered = false;
286	            scheduleNextCommunicationImmediately();
287	        }
288	    }
289	
290	    public long brokerEpoch() {
291	        return brokerEpoch;
292	    }
293	
294	    public BrokerState state() {
295	        return state;
296	    }
297	
298	    public CompletableFuture<Void> initialCatchUpFuture() {
299	        return initialCatchUpFuture;
300	    }
301	
302	    public CompletableFuture<Void> initialUnfenceFuture() {
303	        return initialUnfenceFuture;
304	    }
305	
306	    public CompletableFuture<Void> controlledShutdownFuture() {
307	        return controlledShutdownFuture;
308	    }
309	
310	    public KafkaEventQueue eventQueue() {
311	        return eventQueue;
312	    }
313	
314	    private class BeginControlledShutdownEvent implements EventQueue.Event {
315	        @Override
316	        public void run() {
317	            switch (state) {
318	                case PENDING_CONTROLLED_SHUTDOWN ->
319	                    logger.info("Attempted to enter pending controlled shutdown state, but we are already in that state.");
320	                case RUNNING -> {
321	                    logger.info("Beginning controlled shutdown.");
322	                    state = BrokerState.PENDING_CONTROLLED_SHUTDOWN;
323	                    // Send the next heartbeat immediately in order to let the controller
324	                    // begin processing the controlled shutdown as soon as possible.
325	                    scheduleNextCommunicationImmediately();
326	                }
327	                default -> {
328	                    logger.info("Skipping controlled shutdown because we are in state {}.", state);
329	                    beginShutdown();
330	                }
331	            }
332	        }
333	    }
334	
335	    /**
336	     * Enter the controlled shutdown state if we are in RUNNING state.
337	     * Or, if we're not running, shut down immediately.
338	     */
339	    public void beginControlledShutdown() {
340	        eventQueue.append(new BeginControlledShutdownEvent());
341	    }
342	
343	    /**
344	     * Start shutting down the BrokerLifecycleManager, but do not block.
345	     */
346	    public void beginShutdown() {
347	        eventQueue.beginShutdown("beginShutdown");
348	    }
349	
350	    /**
351	     * Shut down the BrokerLifecycleManager and block until all threads are joined.
352	     */
353	    public void close() throws InterruptedException {
354	        beginShutdown();
355	        eventQueue.close();
356	    }
357	
358	    private class SetReadyToUnfenceEvent implements EventQueue.Event {
359	        @Override
360	        public void run() {
361	            readyToUnfence = true;
362	            scheduleNextCommunicationImmediately();
363	        }
364	    }
365	
366	    private class OfflineDirEvent implements EventQueue.Event {
367	
368	        private final Uuid dir;
369	
370	        OfflineDirEvent(Uuid dir) {
371	            this.dir = dir;
372	        }
373	
374	        @Override
375	        public void run() {
376	            offlineDirs.put(dir, false);
377	            if (registered) {
378	                scheduleNextCommunicationImmediately();
379	            }
380	        }
381	    }
382	
383	    private class OfflineDirBrokerFailureEvent implements EventQueue.Event {
384	
385	        private final Uuid offlineDir;
386	
387	        OfflineDirBrokerFailureEvent(Uuid offlineDir) {
388	            this.offlineDir = offlineDir;
389	        }
390	
391	        @Override
392	        public void run() {
393	            if (!offlineDirs.getOrDefault(offlineDir, false)) {
394	                logger.error("Shutting down because couldn't communicate offline log dir {} with controllers", offlineDir);
395	                shutdownHook.run();
396	            }
397	        }
398	    }
399	
400	    private class StartupEvent implements EventQueue.Event {
401	
402	        private final Supplier<Long> highestMetadataOffsetProvider;
403	        private final NodeToControllerChannelManager channelManager;
404	        private final String clusterId;
405	        private final ListenerCollection advertisedListeners;
406	        private final Map<String, VersionRange> supportedFeatures;
407	
408	        StartupEvent(Supplier<Long> highestMetadataOffsetProvider,
409	                     NodeToControllerChannelManager channelManager,
410	                     String clusterId,
411	                     ListenerCollection advertisedListeners,
412	                     Map<String, VersionRange> supportedFeatures) {
413	            this.highestMetadataOffsetProvider = highestMetadataOffsetProvider;
414	            this.channelManager = channelManager;
415	            this.clusterId = clusterId;
416	            this.advertisedListeners = advertisedListeners;
417	            this.supportedFeatures = supportedFeatures;
418	        }
419	
420	        @Override
421	        public void run() {
422	            BrokerLifecycleManager.this.highestMetadataOffsetProvider = this.highestMetadataOffsetProvider;
423	            BrokerLifecycleManager.this.channelManager = channelManager;
424	            BrokerLifecycleManager.this.channelManager.start();
425	            state = BrokerState.STARTING;
426	            BrokerLifecycleManager.this.clusterId = clusterId;
427	            BrokerLifecycleManager.this.advertisedListeners = advertisedListeners.duplicate();
428	            BrokerLifecycleManager.this.supportedFeatures = Map.copyOf(supportedFeatures);
429	            eventQueue.scheduleDeferred("initialRegistrationTimeout",
430	                    new EventQueue.DeadlineFunction(time.nanoseconds() + initialTimeoutNs),
431	                    new RegistrationTimeoutEvent());
432	            sendBrokerRegistration();
433	            logger.info("Incarnation {} of broker {} in cluster {} is now STARTING.", incarnationId, nodeId, clusterId);
434	        }
435	    }
436	
437	    private void sendBrokerRegistration() {
438	        BrokerRegistrationRequestData.FeatureCollection features = new BrokerRegistrationRequestData.FeatureCollection();
439	        supportedFeatures.forEach((name, range) ->
440	                features.add(new BrokerRegistrationRequestData.Feature()
441	                        .setName(name)
442	                        .setMinSupportedVersion(range.min())
443	                        .setMaxSupportedVersion(range.max()))
444	        );
445	        List<Uuid> sortedLogDirs = new ArrayList<>(logDirs);
446	        sortedLogDirs.sort(Uuid::compareTo);
447	        BrokerRegistrationRequestData data = new BrokerRegistrationRequestData()
448	            .setBrokerId(nodeId)
449	            .setIsMigratingZkBroker(false)
450	            .setClusterId(clusterId)
451	            .setFeatures(features)
452	            .setIncarnationId(incarnationId)
453	            .setListeners(advertisedListeners)
454	            .setRack(rack.orElse(null))
455	            .setPreviousBrokerEpoch(previousBrokerEpoch.orElse(-1L))
456	            .setLogDirs(sortedLogDirs);
457	        if (logger.isDebugEnabled()) {
458	            logger.debug("Sending broker registration {}", data);
459	        }
460	        channelManager.sendRequest(new BrokerRegistrationRequest.Builder(data),
461	                new BrokerRegistrationResponseHandler());
462	        communicationInFlight = true;
463	    }
464	
465	    // the response handler is not invoked from the event handler thread,
466	    // so it is not safe to update state here, instead, schedule an event
467	    // to continue handling the response on the event handler thread
468	    private class BrokerRegistrationResponseHandler implements ControllerRequestCompletionHandler {
469	        @Override
470	        public void onComplete(ClientResponse response) {
471	            eventQueue.prepend(new BrokerRegistrationResponseEvent(response, false));
472	        }
473	
474	        @Override
475	        public void onTimeout() {
476	            logger.info("Unable to register the broker because the RPC got timed out before it could be sent.");
477	            eventQueue.prepend(new BrokerRegistrationResponseEvent(null, true));
478	        }
479	    }
480	
481	    private class BrokerRegistrationResponseEvent implements EventQueue.Event {
482	
483	        private final ClientResponse response;
484	        private final boolean timedOut;
485	
486	        BrokerRegistrationResponseEvent(ClientResponse response, boolean timedOut) {
487	            this.response = response;
488	            this.timedOut = timedOut;
489	        }
490	
491	        @Override
492	        public void run() {
493	            communicationInFlight = false;
494	            if (timedOut) {
495	                scheduleNextCommunicationAfterFailure();
496	                return;
497	            }
498	            if (response.authenticationException() != null) {
499	                logger.error("Unable to register broker $nodeId because of an authentication exception.", response.authenticationException());
500	                scheduleNextCommunicationAfterFailure();
501	            } else if (response.versionMismatch() != null) {
502	                logger.error("Unable to register broker $nodeId because of an API version problem.", response.versionMismatch());
503	                scheduleNextCommunicationAfterFailure();
504	            } else if (response.responseBody() == null) {
505	                logger.warn("Unable to register broker {}.", nodeId);
506	                scheduleNextCommunicationAfterFailure();
507	            } else if (!(response.responseBody() instanceof BrokerRegistrationResponse message)) {
508	                logger.error("Unable to register broker {} because the controller returned an invalid response type.", nodeId);
509	                scheduleNextCommunicationAfterFailure();
510	            } else {
511	                Errors errorCode = Errors.forCode(message.data().errorCode());
512	                if (errorCode == Errors.NONE) {
513	                    brokerEpoch = message.data().brokerEpoch();
514	                    registered = true;
515	                    initialRegistrationSucceeded = true;
516	                    logger.info("Successfully registered broker {} with broker epoch {}", nodeId, brokerEpoch);
517	                    scheduleNextCommunicationImmediately(); // Immediately send a heartbeat
518	                } else {
519	                    logger.info("Unable to register broker {} because the controller returned error {}", nodeId, errorCode);
520	                    scheduleNextCommunicationAfterFailure();
521	                }
522	            }
523	        }
524	    }
525	
526	    private void sendBrokerHeartbeat() {
527	        Long metadataOffset = highestMetadataOffsetProvider.get();
528	        BrokerHeartbeatRequestData data = new BrokerHeartbeatRequestData()
529	            .setBrokerEpoch(brokerEpoch)
530	            .setBrokerId(nodeId)
531	            .setCurrentMetadataOffset(metadataOffset)
532	            .setWantFence(!readyToUnfence)
533	            .setWantShutDown(state == BrokerState.PENDING_CONTROLLED_SHUTDOWN)
534	            .setOfflineLogDirs(new ArrayList<>(offlineDirs.keySet()));
535	        if (logger.isTraceEnabled()) {
536	            logger.trace("Sending broker heartbeat {}", data);
537	        }
538	        BrokerHeartbeatResponseHandler handler = new BrokerHeartbeatResponseHandler(offlineDirs.keySet());
539	        channelManager.sendRequest(new BrokerHeartbeatRequest.Builder(data), handler);
540	        communicationInFlight = true;
541	    }
542	
543	    // the response handler is not invoked from the event handler thread,
544	    // so it is not safe to update state here, instead, schedule an event
545	    // to continue handling the response on the event handler thread
546	    private class BrokerHeartbeatResponseHandler implements ControllerRequestCompletionHandler {
547	
548	        private final Iterable<Uuid> currentOfflineDirs;
549	
550	        BrokerHeartbeatResponseHandler(Iterable<Uuid> currentOfflineDirs) {
551	            this.currentOfflineDirs = currentOfflineDirs;
552	        }
553	
554	        @Override
555	        public void onComplete(ClientResponse response) {
556	            eventQueue.prepend(new BrokerHeartbeatResponseEvent(response, false, currentOfflineDirs));
557	        }
558	
559	        @Override
560	        public void onTimeout() {
561	            logger.info("Unable to send a heartbeat because the RPC got timed out before it could be sent.");
562	            eventQueue.prepend(new BrokerHeartbeatResponseEvent(null, true, currentOfflineDirs));
563	        }
564	    }
565	
566	    private class BrokerHeartbeatResponseEvent implements EventQueue.Event {
567	
568	        private final ClientResponse response;
569	        private final boolean timedOut;
570	        private final Iterable<Uuid> currentOfflineDirs;
571	
572	        BrokerHeartbeatResponseEvent(ClientResponse response, boolean timedOut, Iterable<Uuid> currentOfflineDirs) {
573	            this.response = response;
574	            this.timedOut = timedOut;
575	            this.currentOfflineDirs = currentOfflineDirs;
576	        }
577	
578	        @Override
579	        public void run() {
580	            communicationInFlight = false;
581	            if (timedOut) {
582	                scheduleNextCommunicationAfterFailure();
583	                return;
584	            }
585	            if (response.authenticationException() != null) {
586	                logger.error("Unable to send broker heartbeat for {} because of an authentication exception.",
587	                        nodeId, response.authenticationException());
588	                scheduleNextCommunicationAfterFailure();
589	            } else if (response.versionMismatch() != null) {
590	                logger.error("Unable to send broker heartbeat for {} because of an API version problem.", nodeId, response.versionMismatch());
591	                scheduleNextCommunicationAfterFailure();
592	            } else if (response.responseBody() == null) {
593	                logger.warn("Unable to send broker heartbeat for {}. Retrying.", nodeId);
594	                scheduleNextCommunicationAfterFailure();
595	            } else if (!(response.responseBody() instanceof BrokerHeartbeatResponse message)) {
596	                logger.error("Unable to send broker heartbeat for {} because the controller returned an invalid response type.", nodeId);
597	                scheduleNextCommunicationAfterFailure();
598	            } else {
599	                Errors errorCode = Errors.forCode(message.data().errorCode());
600	                if (errorCode == Errors.NONE) {
601	                    BrokerHeartbeatResponseData responseData = message.data();
602	                    currentOfflineDirs.forEach(cur -> offlineDirs.put(cur, true));
603	                    switch (state) {
604	                        case STARTING -> {
605	                            if (responseData.isCaughtUp()) {
606	                                logger.info("The broker has caught up. Transitioning from STARTING to RECOVERY.");
607	                                state = BrokerState.RECOVERY;
608	                                initialCatchUpFuture.complete(null);
609	                            } else {
610	                                logger.debug("The broker is STARTING. Still waiting to catch up with cluster metadata.");
611	                            }
612	                            // Schedule the heartbeat after only 10 ms so that in the case where
613	                            // there is no recovery work to be done, we start up a bit quicker.
614	                            scheduleNextCommunication(NANOSECONDS.convert(10, MILLISECONDS));
615	                        }
616	                        case RECOVERY -> {
617	                            if (!responseData.isFenced()) {
618	                                logger.info("The broker has been unfenced. Transitioning from RECOVERY to RUNNING.");
619	                                initialUnfenceFuture.complete(null);
620	                                state = BrokerState.RUNNING;
621	                            } else {
622	                                logger.info("The broker is in RECOVERY.");
623	                            }
624	                            scheduleNextCommunicationAfterSuccess();
625	                        }
626	                        case RUNNING -> {
627	                            logger.debug("The broker is RUNNING. Processing heartbeat response.");
628	                            scheduleNextCommunicationAfterSuccess();
629	                        }
630	                        case PENDING_CONTROLLED_SHUTDOWN -> {
631	                            if (!responseData.shouldShutDown()) {
632	                                logger.info("The broker is in PENDING_CONTROLLED_SHUTDOWN state, still waiting " +
633	                                        "for the active controller.");
634	                                if (!gotControlledShutdownResponse) {
635	                                    // If this is the first pending controlled shutdown response we got,
636	                                    // schedule our next heartbeat a little bit sooner than we usually would.
637	                                    // In the case where controlled shutdown completes quickly, this will
638	                                    // speed things up a little bit.
639	                                    scheduleNextCommunication(NANOSECONDS.convert(50, MILLISECONDS));
640	                                } else {
641	                                    scheduleNextCommunicationAfterSuccess();
642	                                }
643	                            } else {
644	                                logger.info("The controller has asked us to exit controlled shutdown.");
645	                                beginShutdown();
646	                            }
647	                            gotControlledShutdownResponse = true;
648	                        }
649	                        case SHUTTING_DOWN -> logger.info("The broker is SHUTTING_DOWN. Ignoring heartbeat response.");
650	                        default -> {
651	                            logger.error("Unexpected broker state {}", state);
652	                            scheduleNextCommunicationAfterSuccess();
653	                        }
654	                    }
655	                } else {
656	                    logger.warn("Broker {} sent a heartbeat request but received error {}.", nodeId, errorCode);
657	                    scheduleNextCommunicationAfterFailure();
658	                }
659	            }
660	        }
661	    }
662	
663	    private void scheduleNextCommunicationImmediately() {
664	        scheduleNextCommunication(0);
665	    }
666	
667	    private void scheduleNextCommunicationAfterFailure() {
668	        nextSchedulingShouldBeImmediate = false; // never immediately reschedule after a failure
669	        scheduleNextCommunication(NANOSECONDS.convert(config.brokerHeartbeatIntervalMs(), MILLISECONDS));
670	    }
671	
672	    private void scheduleNextCommunicationAfterSuccess() {
673	        scheduleNextCommunication(NANOSECONDS.convert(config.brokerHeartbeatIntervalMs(), MILLISECONDS));
674	    }
675	
676	    private void scheduleNextCommunication(long intervalNs) {
677	        long adjustedIntervalNs = nextSchedulingShouldBeImmediate ? 0 : intervalNs;
678	        nextSchedulingShouldBeImmediate = false;
679	        logger.trace("Scheduling next communication at {}ms from now.", MILLISECONDS.convert(adjustedIntervalNs, NANOSECONDS));
680	        long deadlineNs = time.nanoseconds() + adjustedIntervalNs;
681	        eventQueue.scheduleDeferred("communication", new EventQueue.DeadlineFunction(deadlineNs), new CommunicationEvent());
682	    }
683	
684	    private class RegistrationTimeoutEvent implements EventQueue.Event {
685	        @Override
686	        public void run() {
687	            if (!initialRegistrationSucceeded) {
688	                logger.error("Shutting down because we were unable to register with the controller quorum.");
689	                eventQueue.beginShutdown("registrationTimeout");
690	            }
691	        }
692	    }
693	
694	    private class CommunicationEvent implements EventQueue.Event {
695	        @Override
696	        public void run() {
697	            if (communicationInFlight) {
698	                logger.trace("Delaying communication because there is already one in flight.");
699	                nextSchedulingShouldBeImmediate = true;
700	            } else if (registered) {
701	                sendBrokerHeartbeat();
702	            } else {
703	                sendBrokerRegistration();
704	            }
705	        }
706	    }
707	
708	    private class ShutdownEvent implements EventQueue.Event {
709	        @Override
710	        public void run() throws InterruptedException {
711	            logger.info("Transitioning from {} to {}.", state, BrokerState.SHUTTING_DOWN);
712	            state = BrokerState.SHUTTING_DOWN;
713	            controlledShutdownFuture.complete(null);
714	            initialCatchUpFuture.cancel(false);
715	            initialUnfenceFuture.cancel(false);
716	            if (channelManager != null) {
717	                channelManager.shutdown();
718	                channelManager = null;
719	            }
720	        }
721	    }
722	}
