17	package org.apache.kafka.server;
18	
19	import org.apache.kafka.clients.ClientResponse;
20	import org.apache.kafka.common.Uuid;
21	import org.apache.kafka.common.message.BrokerHeartbeatRequestData;
22	import org.apache.kafka.common.message.BrokerHeartbeatResponseData;
23	import org.apache.kafka.common.message.BrokerRegistrationRequestData;
24	import org.apache.kafka.common.message.BrokerRegistrationRequestData.ListenerCollection;
25	import org.apache.kafka.common.protocol.Errors;
26	import org.apache.kafka.common.requests.BrokerHeartbeatRequest;
27	import org.apache.kafka.common.requests.BrokerHeartbeatResponse;
28	import org.apache.kafka.common.requests.BrokerRegistrationRequest;
29	import org.apache.kafka.common.requests.BrokerRegistrationResponse;
30	import org.apache.kafka.common.utils.LogContext;
31	import org.apache.kafka.common.utils.Time;
32	import org.apache.kafka.metadata.BrokerState;
33	import org.apache.kafka.metadata.VersionRange;
34	import org.apache.kafka.queue.EventQueue;
35	import org.apache.kafka.queue.KafkaEventQueue;
36	import org.apache.kafka.server.common.ControllerRequestCompletionHandler;
37	import org.apache.kafka.server.common.NodeToControllerChannelManager;
38	import org.apache.kafka.server.config.AbstractKafkaConfig;
39	
40	import org.slf4j.Logger;
41	
42	import java.util.ArrayList;
43	import java.util.HashMap;
44	import java.util.List;
45	import java.util.Map;
46	import java.util.Optional;
47	import java.util.OptionalLong;
48	import java.util.Set;
49	import java.util.concurrent.CompletableFuture;
50	import java.util.function.Supplier;
51	
52	import static java.util.concurrent.TimeUnit.MILLISECONDS;
53	import static java.util.concurrent.TimeUnit.NANOSECONDS;
54	
55	/**
56	 * The broker lifecycle manager owns the broker state.
57	 *
58	 * Its inputs are messages passed in from other parts of the broker and from the
59	 * controller: requests to start up, or shut down, for example. Its output are the broker
60	 * state and various futures that can be used to wait for broker state transitions to
61	 * occur.
62	 *
63	 * The lifecycle manager handles registering the broker with the controller, as described
64	 * in KIP-631. After registration is complete, it handles sending periodic broker
65	 * heartbeats and processing the responses.
66	 *
67	 * This code uses an event queue paradigm. Modifications get translated into events, which
68	 * are placed on the queue to be processed sequentially. As described in the JavaDoc for
69	 * each variable, most mutable state can be accessed only from that event queue thread.
70	 * In some cases we expose a volatile variable which can be read from any thread, but only
71	 * written from the event queue thread.
72	 */
73	public class BrokerLifecycleManager {
74	
75	    private final Logger logger;
76	    private final KafkaEventQueue eventQueue;
77	    private final AbstractKafkaConfig config;
78	    private final Time time;
79	    private final Set<Uuid> logDirs;
80	    private final Runnable shutdownHook;
81	
82	    /**
83	     * The broker id.
84	     */
85	    private final int nodeId;
86	
87	    /**
88	     * The broker rack, or null if there is no configured rack.
89	     */
90	    private final Optional<String> rack;
91	
92	    /**
93	     * How long to wait for registration to succeed before failing the startup process.
94	     */
95	    private final long initialTimeoutNs;
96	
97	    /**
98	     * The broker incarnation ID.  This ID uniquely identifies each time we start the broker
99	     */
100	    private final Uuid incarnationId = Uuid.randomUuid();
101	
102	    /**
103	     * A future which is completed just as soon as the broker has caught up with the latest
104	     * metadata offset for the first time.
105	     */
106	    private final CompletableFuture<Void> initialCatchUpFuture = new CompletableFuture<>();
107	
108	    /**
109	     * A future which is completed when the broker is unfenced for the first time.
110	     */
111	    private final CompletableFuture<Void> initialUnfenceFuture = new CompletableFuture<>();
112	
113	    /**
114	     * A future which is completed when controlled shutdown is done.
115	     */
116	    private final CompletableFuture<Void> controlledShutdownFuture = new CompletableFuture<>();
117	
118	    /**
119	     * The broker epoch, or -1 if the broker has not yet registered.  This variable can only
120	     * be written from the event queue thread.
121	     */
122	    private volatile long brokerEpoch = -1L;
123	
124	    /**
125	     * The current broker state.  This variable can only be written from the event queue
126	     * thread.
127	     */
128	    private volatile BrokerState state = BrokerState.NOT_RUNNING;
129	
130	    /**
131	     * A thread-safe callback function which gives this manager the current highest metadata
132	     * offset.  This variable can only be read or written from the event queue thread.
133	     */
134	    private Supplier<Long> highestMetadataOffsetProvider;
135	
136	    /**
137	     * True only if we are ready to unfence the broker.  This variable can only be read or
138	     * written from the event queue thread.
139	     */
140	    private boolean readyToUnfence = false;
141	
142	    /**
143	     * Map of accumulated offline directories. The value is true if the directory has been successfully communicated
144	     * to the Controller.
145	     * This variable can only be read or written from the event queue thread.
146	     */
147	    private Map<Uuid, Boolean> offlineDirs = new HashMap<>();
148	
149	    /**
150	     * True if we sent an event queue to the active controller requesting controlled
151	     * shutdown.  This variable can only be read or written from the event queue thread.
152	     */
153	    private boolean gotControlledShutdownResponse = false;
154	
155	    /**
156	     * Whether this broker is registered with the controller quorum.
157	     * This variable can only be read or written from the event queue thread.
158	     */
159	    private boolean registered = false;
160	
161	    /**
162	     * True if a request has been sent and a response or timeout has not yet been processed.
