400	    private class StartupEvent implements EventQueue.Event {
401	
402	        private final Supplier<Long> highestMetadataOffsetProvider;
403	        private final NodeToControllerChannelManager channelManager;
404	        private final String clusterId;
405	        private final ListenerCollection advertisedListeners;
406	        private final Map<String, VersionRange> supportedFeatures;
407	
408	        StartupEvent(Supplier<Long> highestMetadataOffsetProvider,
409	                     NodeToControllerChannelManager channelManager,
410	                     String clusterId,
411	                     ListenerCollection advertisedListeners,
412	                     Map<String, VersionRange> supportedFeatures) {
413	            this.highestMetadataOffsetProvider = highestMetadataOffsetProvider;
414	            this.channelManager = channelManager;
415	            this.clusterId = clusterId;
416	            this.advertisedListeners = advertisedListeners;
417	            this.supportedFeatures = supportedFeatures;
418	        }
419	
420	        @Override
421	        public void run() {
422	            BrokerLifecycleManager.this.highestMetadataOffsetProvider = this.highestMetadataOffsetProvider;
423	            BrokerLifecycleManager.this.channelManager = channelManager;
424	            BrokerLifecycleManager.this.channelManager.start();
425	            state = BrokerState.STARTING;
426	            BrokerLifecycleManager.this.clusterId = clusterId;
427	            BrokerLifecycleManager.this.advertisedListeners = advertisedListeners.duplicate();
428	            BrokerLifecycleManager.this.supportedFeatures = Map.copyOf(supportedFeatures);
429	            eventQueue.scheduleDeferred("initialRegistrationTimeout",
430	                    new EventQueue.DeadlineFunction(time.nanoseconds() + initialTimeoutNs),
431	                    new RegistrationTimeoutEvent());
432	            sendBrokerRegistration();
433	            logger.info("Incarnation {} of broker {} in cluster {} is now STARTING.", incarnationId, nodeId, clusterId);
434	        }
435	    }
