437	    private void sendBrokerRegistration() {
438	        BrokerRegistrationRequestData.FeatureCollection features = new BrokerRegistrationRequestData.FeatureCollection();
439	        supportedFeatures.forEach((name, range) ->
440	                features.add(new BrokerRegistrationRequestData.Feature()
441	                        .setName(name)
442	                        .setMinSupportedVersion(range.min())
443	                        .setMaxSupportedVersion(range.max()))
444	        );
445	        List<Uuid> sortedLogDirs = new ArrayList<>(logDirs);
446	        sortedLogDirs.sort(Uuid::compareTo);
447	        BrokerRegistrationRequestData data = new BrokerRegistrationRequestData()
448	            .setBrokerId(nodeId)
449	            .setIsMigratingZkBroker(false)
450	            .setClusterId(clusterId)
451	            .setFeatures(features)
452	            .setIncarnationId(incarnationId)
453	            .setListeners(advertisedListeners)
454	            .setRack(rack.orElse(null))
455	            .setPreviousBrokerEpoch(previousBrokerEpoch.orElse(-1L))
456	            .setLogDirs(sortedLogDirs);
457	        if (logger.isDebugEnabled()) {
458	            logger.debug("Sending broker registration {}", data);
459	        }
460	        channelManager.sendRequest(new BrokerRegistrationRequest.Builder(data),
461	                new BrokerRegistrationResponseHandler());
462	        communicationInFlight = true;
463	    }
