465	    // the response handler is not invoked from the event handler thread,
466	    // so it is not safe to update state here, instead, schedule an event
467	    // to continue handling the response on the event handler thread
468	    private class BrokerRegistrationResponseHandler implements ControllerRequestCompletionHandler {
469	        @Override
470	        public void onComplete(ClientResponse response) {
471	            eventQueue.prepend(new BrokerRegistrationResponseEvent(response, false));
472	        }
473	
474	        @Override
475	        public void onTimeout() {
476	            logger.info("Unable to register the broker because the RPC got timed out before it could be sent.");
477	            eventQueue.prepend(new BrokerRegistrationResponseEvent(null, true));
478	        }
479	    }
480	
481	    private class BrokerRegistrationResponseEvent implements EventQueue.Event {
482	
483	        private final ClientResponse response;
484	        private final boolean timedOut;
485	
486	        BrokerRegistrationResponseEvent(ClientResponse response, boolean timedOut) {
487	            this.response = response;
488	            this.timedOut = timedOut;
489	        }
490	
491	        @Override
492	        public void run() {
493	            communicationInFlight = false;
494	            if (timedOut) {
495	                scheduleNextCommunicationAfterFailure();
496	                return;
497	            }
498	            if (response.authenticationException() != null) {
499	                logger.error("Unable to register broker $nodeId because of an authentication exception.", response.authenticationException());
500	                scheduleNextCommunicationAfterFailure();
501	            } else if (response.versionMismatch() != null) {
502	                logger.error("Unable to register broker $nodeId because of an API version problem.", response.versionMismatch());
503	                scheduleNextCommunicationAfterFailure();
504	            } else if (response.responseBody() == null) {
505	                logger.warn("Unable to register broker {}.", nodeId);
506	                scheduleNextCommunicationAfterFailure();
507	            } else if (!(response.responseBody() instanceof BrokerRegistrationResponse message)) {
508	                logger.error("Unable to register broker {} because the controller returned an invalid response type.", nodeId);
509	                scheduleNextCommunicationAfterFailure();
510	            } else {
511	                Errors errorCode = Errors.forCode(message.data().errorCode());
512	                if (errorCode == Errors.NONE) {
513	                    brokerEpoch = message.data().brokerEpoch();
514	                    registered = true;
515	                    initialRegistrationSucceeded = true;
516	                    logger.info("Successfully registered broker {} with broker epoch {}", nodeId, brokerEpoch);
517	                    scheduleNextCommunicationImmediately(); // Immediately send a heartbeat
518	                } else {
519	                    logger.info("Unable to register broker {} because the controller returned error {}", nodeId, errorCode);
520	                    scheduleNextCommunicationAfterFailure();
521	                }
522	            }
523	        }
524	    }
