156	    private BrokerRegistration(
157	        int id,
158	        long epoch,
159	        Uuid incarnationId,
160	        Map<String, Endpoint> listeners,
161	        Map<String, VersionRange> supportedFeatures,
162	        Optional<String> rack,
163	        boolean fenced,
164	        boolean inControlledShutdown,
165	        boolean isMigratingZkBroker,
166	        List<Uuid> directories
167	    ) {
168	        this.id = id;
169	        this.epoch = epoch;
170	        this.incarnationId = incarnationId;
171	        Map<String, Endpoint> newListeners = new HashMap<>(listeners.size());
172	        for (Entry<String, Endpoint> entry : listeners.entrySet()) {
173	            if (entry.getValue().listener().isEmpty()) {
174	                throw new IllegalArgumentException("Broker listeners must be named.");
175	            }
176	            newListeners.put(entry.getKey(), entry.getValue());
177	        }
178	        this.listeners = Collections.unmodifiableMap(newListeners);
179	        Objects.requireNonNull(supportedFeatures);
180	        this.supportedFeatures = new HashMap<>(supportedFeatures);
181	        this.rack = rack;
182	        this.fenced = fenced;
183	        this.inControlledShutdown = inControlledShutdown;
184	        this.isMigratingZkBroker = isMigratingZkBroker;
185	        directories = new ArrayList<>(directories);
186	        directories.sort(Uuid::compareTo);
187	        this.directories = Collections.unmodifiableList(directories);
188	    }
