190	    public static BrokerRegistration fromRecord(RegisterBrokerRecord record) {
191	        Map<String, Endpoint> listeners = new HashMap<>();
192	        for (BrokerEndpoint endpoint : record.endPoints()) {
193	            listeners.put(endpoint.name(), new Endpoint(endpoint.name(),
194	                SecurityProtocol.forId(endpoint.securityProtocol()),
195	                endpoint.host(),
196	                endpoint.port()));
197	        }
198	        Map<String, VersionRange> supportedFeatures = new HashMap<>();
199	        for (BrokerFeature feature : record.features()) {
200	            supportedFeatures.put(feature.name(), VersionRange.of(
201	                feature.minSupportedVersion(), feature.maxSupportedVersion()));
202	        }
203	        return new BrokerRegistration(record.brokerId(),
204	            record.brokerEpoch(),
205	            record.incarnationId(),
206	            listeners,
207	            supportedFeatures,
208	            Optional.ofNullable(record.rack()),
209	            record.fenced(),
210	            record.inControlledShutdown(),
211	            record.isMigratingZkBroker(),
212	            record.logDirs());
213	    }
