349	    public ControllerResult<BrokerRegistrationReply> registerBroker(
350	        BrokerRegistrationRequestData request,
351	        long newBrokerEpoch,
352	        FinalizedControllerFeatures finalizedFeatures,
353	        boolean cleanShutdownDetectionEnabled
354	    ) {
355	        if (heartbeatManager == null) {
356	            throw new RuntimeException("ClusterControlManager is not active.");
357	        }
358	        if (!clusterId.equals(request.clusterId())) {
359	            throw new InconsistentClusterIdException("Expected cluster ID " + clusterId +
360	                ", but got cluster ID " + request.clusterId());
361	        }
362	        int brokerId = request.brokerId();
363	        List<ApiMessageAndVersion> records = new ArrayList<>();
364	        BrokerRegistration existing = brokerRegistrations.get(brokerId);
365	        Uuid prevIncarnationId = null;
366	        long storedBrokerEpoch = -2; // BrokerRegistration.previousBrokerEpoch default value is -1
367	        if (existing != null) {
368	            prevIncarnationId = existing.incarnationId();
369	            storedBrokerEpoch = existing.epoch();
370	            if (heartbeatManager.hasValidSession(brokerId, existing.epoch())) {
371	                if (!request.incarnationId().equals(prevIncarnationId)) {
372	                    throw new DuplicateBrokerRegistrationException("Another broker is registered with that broker id. If the broker " +
373	                            "was recently restarted this should self-resolve once the heartbeat manager expires the broker's session.");
374	                }
375	            }
376	        }
377	
378	        if (request.isMigratingZkBroker()) {
379	            throw new BrokerIdNotRegisteredException("Controller does not support registering ZK brokers.");
380	        }
381	
382	        if (featureControl.metadataVersionOrThrow().isDirectoryAssignmentSupported()) {
383	            if (request.logDirs().isEmpty()) {
384	                throw new InvalidRegistrationException("No directories specified in request");
385	            }
386	            if (request.logDirs().stream().anyMatch(DirectoryId::reserved)) {
387	                throw new InvalidRegistrationException("Reserved directory ID in request");
388	            }
389	            Set<Uuid> set = new HashSet<>(request.logDirs());
390	            if (set.size() != request.logDirs().size()) {
391	                throw new InvalidRegistrationException("Duplicate directory ID in request");
392	            }
393	            for (Uuid directory : request.logDirs()) {
394	                Integer dirBrokerId = directoryToBroker.get(directory);
395	                if (dirBrokerId != null && dirBrokerId != brokerId) {
396	                    throw new InvalidRegistrationException("Broker " + dirBrokerId +
397	                            " is already registered with directory " + directory);
398	                }
399	            }
400	        }
401	
402	        ListenerInfo listenerInfo = ListenerInfo.fromBrokerRegistrationRequest(request.listeners());
403	        RegisterBrokerRecord record = new RegisterBrokerRecord().
404	            setBrokerId(brokerId).
405	            setIsMigratingZkBroker(request.isMigratingZkBroker()).
406	            setIncarnationId(request.incarnationId()).
407	            setRack(request.rack()).
408	            setEndPoints(listenerInfo.toBrokerRegistrationRecord());
409	
410	        // Track which finalized features we have not yet verified are supported by the broker.
411	        Map<String, Short> unverifiedFeatures = new HashMap<>(finalizedFeatures.featureMap());
412	
413	        // Check every broker feature version range includes the finalized version.
414	        for (BrokerRegistrationRequestData.Feature feature : request.features()) {
415	            record.features().add(processRegistrationFeature(brokerId, finalizedFeatures, feature));
416	            unverifiedFeatures.remove(feature.name());
417	        }
418	
419	        if (request.features().find(MetadataVersion.FEATURE_NAME) == null)
420	            throw new InvalidRegistrationException("Request features do not contain '" + MetadataVersion.FEATURE_NAME + "'");
421	
422	        // We also need to check every controller feature is supported by the broker.
423	        unverifiedFeatures.forEach((featureName, finalizedVersion) -> {
424	            if (finalizedVersion != 0 && request.features().findAll(featureName).isEmpty()) {
425	                processRegistrationFeature(brokerId, finalizedFeatures,
426	                    new BrokerRegistrationRequestData.Feature().
427	                        setName(featureName).
428	                        setMinSupportedVersion((short) 0).
429	                        setMaxSupportedVersion((short) 0));
430	            }
431	        });
432	        if (featureControl.metadataVersionOrThrow().isDirectoryAssignmentSupported()) {
433	            record.setLogDirs(request.logDirs());
434	        }
435	
436	        if (!request.incarnationId().equals(prevIncarnationId)) {
437	            int prevNumRecords = records.size();
438	            boolean isCleanShutdown = cleanShutdownDetectionEnabled ?
439	                storedBrokerEpoch == request.previousBrokerEpoch() : false;
440	            brokerShutdownHandler.addRecordsForShutdown(request.brokerId(), isCleanShutdown, records);
441	            int numRecordsAdded = records.size() - prevNumRecords;
442	            if (existing == null) {
443	                log.info("No previous registration found for broker {}. New incarnation ID is " +
444	                        "{}.  Generated {} record(s) to clean up previous incarnations. New broker " +
445	                        "epoch is {}.", brokerId, request.incarnationId(), numRecordsAdded, newBrokerEpoch);
446	                metrics.addTimeSinceLastHeartbeatMetric(brokerId);
447	            } else {
448	                log.info("Registering a new incarnation of broker {}. Previous incarnation ID " +
449	                        "was {}; new incarnation ID is {}. Generated {} record(s) to clean up " +
450	                        "previous incarnations. Broker epoch will become {}.", brokerId,
451	                        existing.incarnationId(), request.incarnationId(), numRecordsAdded,
452	                        newBrokerEpoch);
453	            }
454	            record.setBrokerEpoch(newBrokerEpoch);
455	        } else {
456	            log.info("Amending registration of broker {}, incarnation ID {}. Broker epoch remains {}.",
457	                    request.brokerId(), request.incarnationId(), existing.epoch());
458	            record.setFenced(existing.fenced());
459	            record.setInControlledShutdown(existing.inControlledShutdown());
460	            record.setBrokerEpoch(existing.epoch());
461	        }
462	        records.add(new ApiMessageAndVersion(record, featureControl.metadataVersionOrThrow().
463	            registerBrokerRecordVersion()));
464	
465	        if (!request.incarnationId().equals(prevIncarnationId)) {
466	            // Remove any existing session for the old broker incarnation.
467	            heartbeatManager.remove(brokerId);
468	        }
469	        heartbeatManager.register(brokerId, record.fenced());
470	
471	        // A broker registration that cleans up a previous incarnation's unclean shutdown may generate a large number of records.
472	        // It is safe to return these records as a non-atomic batch as long as the registration record is added last.
473	        // This ensures that in case of a controller failure, the broker will re-register and the new controller
474	        // can retry the unclean shutdown cleanup.
475	        return ControllerResult.of(records, new BrokerRegistrationReply(record.brokerEpoch()));
476	    }
477	
478	    ControllerResult<Void> registerController(ControllerRegistrationRequestData request) {
479	        if (!featureControl.metadataVersionOrThrow().isControllerRegistrationSupported()) {
480	            throw new UnsupportedVersionException("The current MetadataVersion is too old to " +
481	                    "support controller registrations.");
482	        }
483	        ListenerInfo listenerInfo = ListenerInfo.fromControllerRegistrationRequest(request.listeners());
484	        ControllerFeatureCollection features = new ControllerFeatureCollection();
485	        request.features().forEach(feature ->
486	            features.add(new RegisterControllerRecord.ControllerFeature().
487	                setName(feature.name()).
488	                setMaxSupportedVersion(feature.maxSupportedVersion()).
489	                setMinSupportedVersion(feature.minSupportedVersion()))
490	        );
491	        List<ApiMessageAndVersion> records = new ArrayList<>();
492	        records.add(new ApiMessageAndVersion(new RegisterControllerRecord().
493	            setControllerId(request.controllerId()).
494	            setIncarnationId(request.incarnationId()).
495	            setZkMigrationReady(false).
496	            setEndPoints(listenerInfo.toControllerRegistrationRecord()).
497	            setFeatures(features),
498	                (short) 0));
499	        return ControllerResult.atomicOf(records, null);
500	    }
501	
502	    BrokerFeature processRegistrationFeature(
503	        int brokerId,
504	        FinalizedControllerFeatures finalizedFeatures,
505	        BrokerRegistrationRequestData.Feature feature
506	    ) {
507	        // MetadataVersion has no default while the other features default to `0`
508	        short finalized;
509	        if (feature.name().equals(MetadataVersion.FEATURE_NAME))
510	            finalized = finalizedFeatures.get(feature.name()).orElseThrow(() ->
511	                new IllegalArgumentException("Feature with name '" + MetadataVersion.FEATURE_NAME + "' not found in finalizedFeatures " + finalizedFeatures));
512	        else
513	            finalized = finalizedFeatures.versionOrDefault(feature.name(), (short) 0);
514	
515	        if (!VersionRange.of(feature.minSupportedVersion(), feature.maxSupportedVersion()).contains(finalized)) {
516	            throw new UnsupportedVersionException("Unable to register because the broker " +
517	                "does not support finalized version " + finalized + " of " + feature.name() +
518	                    ". The broker wants a version between " + feature.minSupportedVersion() + " and " +
519	                    feature.maxSupportedVersion() + ", inclusive.");
520	        }
521	        // A feature is not found in the finalizedFeature map if it is unknown to the controller or set to 0 (feature not enabled).
522	        if (!finalizedFeatures.featureNames().contains(feature.name()))
523	            log.debug("Broker {} registered with version range ({}, {}] of feature {} which controller does not know " +
524	                    "or has finalized version of 0.",
525	                    brokerId, feature.minSupportedVersion(), feature.maxSupportedVersion(), feature.name());
526	        return new BrokerFeature().
527	                setName(feature.name()).
528	                setMinSupportedVersion(feature.minSupportedVersion()).
529	                setMaxSupportedVersion(feature.maxSupportedVersion());
530	    }
531	
532	    /**
533	     * Track an incoming broker heartbeat. Unlike most functions, this one is not called from the main
534	     * controller thread, so it can only access local, volatile and atomic data.
535	     *
536	     * @param brokerId      The broker id to track.
537	     * @param brokerEpoch   The broker epoch to track.
538	     *
539	     * @return              True only if the ClusterControlManager is active.
540	     */
541	    boolean trackBrokerHeartbeat(int brokerId, long brokerEpoch) {
542	        BrokerHeartbeatManager manager = heartbeatManager;
543	        if (manager == null) return false;
544	        manager.tracker().updateContactTime(new BrokerIdAndEpoch(brokerId, brokerEpoch));
545	        return true;
546	    }
547	
548	    public OptionalLong registerBrokerRecordOffset(int brokerId) {
549	        Long registrationOffset = registerBrokerRecordOffsets.get(brokerId);
550	        if (registrationOffset != null) {
551	            return OptionalLong.of(registrationOffset);
552	        }
553	        return OptionalLong.empty();
554	    }
555	
556	    public void replay(RegisterBrokerRecord record, long offset) {
557	        registerBrokerRecordOffsets.put(record.brokerId(), offset);
558	        int brokerId = record.brokerId();
559	        ListenerInfo listenerInfo = ListenerInfo.fromBrokerRegistrationRecord(record.endPoints());
560	        Map<String, VersionRange> features = new HashMap<>();
561	        for (BrokerFeature feature : record.features()) {
562	            features.put(feature.name(), VersionRange.of(
563	                feature.minSupportedVersion(), feature.maxSupportedVersion()));
564	        }
565	        // Update broker registrations.
566	        BrokerRegistration prevRegistration = brokerRegistrations.put(brokerId,
567	            new BrokerRegistration.Builder().
568	                setId(brokerId).
569	                setEpoch(record.brokerEpoch()).
570	                setIncarnationId(record.incarnationId()).
571	                setListeners(listenerInfo.listeners()).
572	                setSupportedFeatures(features).
573	                setRack(Optional.ofNullable(record.rack())).
574	                setFenced(record.fenced()).
575	                setInControlledShutdown(record.inControlledShutdown()).
576	                setIsMigratingZkBroker(record.isMigratingZkBroker()).
577	                setDirectories(record.logDirs()).
578	                    build());
579	        updateDirectories(brokerId, prevRegistration == null ? null : prevRegistration.directories(), record.logDirs());
580	        if (heartbeatManager != null) {
581	            if (prevRegistration != null) heartbeatManager.remove(brokerId);
582	            heartbeatManager.register(brokerId, record.fenced());
583	        }
584	        if (prevRegistration == null) {
585	            log.info("Replayed initial RegisterBrokerRecord for broker {}: {}", record.brokerId(), record);
586	        } else if (prevRegistration.incarnationId().equals(record.incarnationId())) {
587	            log.info("Replayed RegisterBrokerRecord modifying the registration for broker {}: {}",
588	                record.brokerId(), record);
589	        } else {
590	            log.info("Replayed RegisterBrokerRecord establishing a new incarnation of broker {}: {}",
591	                record.brokerId(), record);
592	        }
593	    }
594	
595	    public void replay(UnregisterBrokerRecord record) {
596	        registerBrokerRecordOffsets.remove(record.brokerId());
597	        int brokerId = record.brokerId();
598	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
599	        if (registration == null) {
600	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
601	                "registration found for that id", record));
602	        } else if (registration.epoch() != record.brokerEpoch()) {
603	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
604	                "registration with that epoch found", record));
605	        } else {
606	            if (heartbeatManager != null) heartbeatManager.remove(brokerId);
607	            updateDirectories(brokerId, registration.directories(), null);
608	            brokerRegistrations.remove(brokerId);
609	            log.info("Replayed {}", record);
610	        }
611	    }
612	
613	    public void replay(FenceBrokerRecord record) {
614	        replayRegistrationChange(
615	            record,
616	            record.id(),
617	            record.epoch(),
618	            BrokerRegistrationFencingChange.FENCE.asBoolean(),
619	            BrokerRegistrationInControlledShutdownChange.NONE.asBoolean(),
620	            Optional.empty()
621	        );
622	    }
623	
624	    public void replay(UnfenceBrokerRecord record) {
625	        replayRegistrationChange(
626	            record,
627	            record.id(),
628	            record.epoch(),
629	            BrokerRegistrationFencingChange.UNFENCE.asBoolean(),
630	            BrokerRegistrationInControlledShutdownChange.NONE.asBoolean(),
631	            Optional.empty()
632	        );
633	    }
634	
635	    public void replay(BrokerRegistrationChangeRecord record) {
636	        BrokerRegistrationFencingChange fencingChange =
637	            BrokerRegistrationFencingChange.fromValue(record.fenced()).orElseThrow(
638	                () -> new IllegalStateException(String.format("Unable to replay %s: unknown " +
639	                    "value for fenced field: %x", record, record.fenced())));
640	        BrokerRegistrationInControlledShutdownChange inControlledShutdownChange =
641	            BrokerRegistrationInControlledShutdownChange.fromValue(record.inControlledShutdown()).orElseThrow(
642	                () -> new IllegalStateException(String.format("Unable to replay %s: unknown " +
643	                    "value for inControlledShutdown field: %x", record, record.inControlledShutdown())));
644	        Optional<List<Uuid>> directoriesChange = Optional.ofNullable(record.logDirs()).filter(list -> !list.isEmpty());
645	        replayRegistrationChange(
646	            record,
647	            record.brokerId(),
648	            record.brokerEpoch(),
649	            fencingChange.asBoolean(),
650	            inControlledShutdownChange.asBoolean(),
651	            directoriesChange
652	        );
653	    }
654	
655	    private void replayRegistrationChange(
656	        ApiMessage record,
657	        int brokerId,
658	        long brokerEpoch,
659	        Optional<Boolean> fencingChange,
660	        Optional<Boolean> inControlledShutdownChange,
661	        Optional<List<Uuid>> directoriesChange
662	    ) {
663	        BrokerRegistration curRegistration = brokerRegistrations.get(brokerId);
664	        if (curRegistration == null) {
665	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
666	                "registration found for that id", record.toString()));
667	        } else if (curRegistration.epoch() != brokerEpoch) {
668	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
669	                "registration with that epoch found", record.toString()));
670	        } else {
671	            BrokerRegistration nextRegistration = curRegistration.cloneWith(
672	                fencingChange,
673	                inControlledShutdownChange,
674	                directoriesChange
675	            );
676	            if (!curRegistration.equals(nextRegistration)) {
677	                log.info("Replayed {} modifying the registration for broker {}: {}",
678	                        record.getClass().getSimpleName(), brokerId, record);
679	                brokerRegistrations.put(brokerId, nextRegistration);
680	            } else {
681	                log.info("Ignoring no-op registration change for {}", curRegistration);
682	            }
683	            updateDirectories(brokerId, curRegistration.directories(), nextRegistration.directories());
684	            if (heartbeatManager != null) heartbeatManager.register(brokerId, nextRegistration.fenced());
685	            if (readyBrokersFuture.isPresent()) {
686	                if (readyBrokersFuture.get().check()) {
687	                    readyBrokersFuture.get().future.complete(null);
688	                    readyBrokersFuture = Optional.empty();
689	                }
690	            }
691	        }
692	    }
693	
694	    public void replay(RegisterControllerRecord record) {
695	        ControllerRegistration newRegistration = new ControllerRegistration.Builder(record).build();
696	        ControllerRegistration prevRegistration =
697	            controllerRegistrations.put(record.controllerId(), newRegistration);
698	        log.info("Replayed RegisterControllerRecord containing {}.{}", newRegistration,
699	            prevRegistration == null ? "" :
700	                " Previous incarnation was " + prevRegistration.incarnationId());
701	    }
702	
703	    Iterator<UsableBroker> usableBrokers() {
704	        if (heartbeatManager == null) {
705	            throw new RuntimeException("ClusterControlManager is not active.");
706	        }
707	        return heartbeatManager.usableBrokers(
708	            id -> brokerRegistrations.get(id).rack());
709	    }
710	
711	    /**
712	     * Returns true if the broker is unfenced; Returns false if it is
713	     * not or if it does not exist.
714	     */
715	    public boolean isUnfenced(int brokerId) {
716	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
717	        if (registration == null) return false;
718	        return !registration.fenced();
719	    }
720	
721	    /**
722	     * Get a broker registration if it exists.
723	     *
724	     * @param brokerId The brokerId to get the registration for
725	     * @return The current registration or null if the broker is not registered
726	     */
727	    public BrokerRegistration registration(int brokerId) {
728	        return brokerRegistrations.get(brokerId);
729	    }
730	
731	    /**
732	     * Returns true if the broker is in controlled shutdown state; Returns false
733	     * if it is not or if it does not exist.
734	     */
735	    public boolean inControlledShutdown(int brokerId) {
736	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
737	        if (registration == null) return false;
738	        return registration.inControlledShutdown();
739	    }
740	
741	    /**
742	     * Returns true if the broker is active. Active means not fenced nor in controlled
743	     * shutdown; Returns false if it is not active or if it does not exist.
744	     */
745	    public boolean isActive(int brokerId) {
746	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
747	        if (registration == null) return false;
748	        return !registration.inControlledShutdown() && !registration.fenced();
749	    }
750	
751	    BrokerHeartbeatManager heartbeatManager() {
752	        // We throw RuntimeException here rather than NotControllerException because all the callers
753	        // have already verified that we are active. For example, ControllerWriteEvent.run verifies
754	        // that we are the current active controller before running any event-specific code.
755	        if (heartbeatManager == null) {
756	            throw new RuntimeException("ClusterControlManager is not active.");
757	        }
758	        return heartbeatManager;
759	    }
760	
761	    public void checkBrokerEpoch(int brokerId, long brokerEpoch) {
762	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
763	        if (registration == null) {
764	            throw new StaleBrokerEpochException("No broker registration found for " +
765	                "broker id " + brokerId);
766	        }
767	        if (registration.epoch() != brokerEpoch) {
768	            throw new StaleBrokerEpochException("Expected broker epoch " +
769	                registration.epoch() + ", but got broker epoch " + brokerEpoch);
770	        }
771	    }
772	
773	    public void addReadyBrokersFuture(CompletableFuture<Void> future, int minBrokers) {
774	        readyBrokersFuture = Optional.of(new ReadyBrokersFuture(future, minBrokers));
775	        if (readyBrokersFuture.get().check()) {
776	            readyBrokersFuture.get().future.complete(null);
777	            readyBrokersFuture = Optional.empty();
778	        }
779	    }

