312	    public void activate() {
313	        heartbeatManager = new BrokerHeartbeatManager(logContext, time, sessionTimeoutNs);
314	        long nowNs = time.nanoseconds();
315	        for (BrokerRegistration registration : brokerRegistrations.values()) {
316	            int brokerId = registration.id();
317	            heartbeatManager.register(brokerId, registration.fenced());
318	            metrics.addTimeSinceLastHeartbeatMetric(brokerId);
319	            if (!registration.fenced()) {
320	                heartbeatManager.tracker().updateContactTime(
321	                    new BrokerIdAndEpoch(brokerId, registration.epoch()), nowNs);
322	            }
323	        }
324	    }
