595	    public void replay(UnregisterBrokerRecord record) {
596	        registerBrokerRecordOffsets.remove(record.brokerId());
597	        int brokerId = record.brokerId();
598	        BrokerRegistration registration = brokerRegistrations.get(brokerId);
599	        if (registration == null) {
600	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
601	                "registration found for that id", record));
602	        } else if (registration.epoch() != record.brokerEpoch()) {
603	            throw new RuntimeException(String.format("Unable to replay %s: no broker " +
604	                "registration with that epoch found", record));
605	        } else {
606	            if (heartbeatManager != null) heartbeatManager.remove(brokerId);
607	            updateDirectories(brokerId, registration.directories(), null);
608	            brokerRegistrations.remove(brokerId);
609	            log.info("Replayed {}", record);
610	        }
611	    }
