1534	    ControllerResult<ElectLeadersResponseData> electLeaders(ElectLeadersRequestData request) {
1535	        ElectionType electionType = electionType(request.electionType());
1536	        List<ApiMessageAndVersion> records = BoundedList.newArrayBacked(MAX_RECORDS_PER_USER_OP);
1537	        ElectLeadersResponseData response = new ElectLeadersResponseData();
1538	        if (request.topicPartitions() == null) {
1539	            // If topicPartitions is null, we try to elect a new leader for every partition.  There
1540	            // are some obvious issues with this wire protocol.  For example, what if we have too
1541	            // many partitions to fit the results in a single RPC?  This behavior should probably be
1542	            // removed from the protocol.  For now, however, we have to implement this for
1543	            // compatibility with the old controller.
1544	            for (Entry<String, Uuid> topicEntry : topicsByName.entrySet()) {
1545	                String topicName = topicEntry.getKey();
1546	                ReplicaElectionResult topicResults =
1547	                    new ReplicaElectionResult().setTopic(topicName);
1548	                response.replicaElectionResults().add(topicResults);
1549	                TopicControlInfo topic = topics.get(topicEntry.getValue());
1550	                if (topic != null) {
1551	                    for (int partitionId : topic.parts.keySet()) {
1552	                        ApiError error = electLeader(topicName, partitionId, electionType, records);
1553	
1554	                        // When electing leaders for all partitions, we do not return
1555	                        // partitions which already have the desired leader.
1556	                        if (error.error() != Errors.ELECTION_NOT_NEEDED) {
1557	                            topicResults.partitionResult().add(new PartitionResult().
1558	                                setPartitionId(partitionId).
1559	                                setErrorCode(error.error().code()).
1560	                                setErrorMessage(error.message()));
1561	                        }
1562	                    }
1563	                }
1564	            }
1565	        } else {
1566	            for (TopicPartitions topic : request.topicPartitions()) {
1567	                ReplicaElectionResult topicResults =
1568	                    new ReplicaElectionResult().setTopic(topic.topic());
1569	                response.replicaElectionResults().add(topicResults);
1570	                for (int partitionId : topic.partitions()) {
1571	                    ApiError error = electLeader(topic.topic(), partitionId, electionType, records);
1572	                    topicResults.partitionResult().add(new PartitionResult().
1573	                        setPartitionId(partitionId).
1574	                        setErrorCode(error.error().code()).
1575	                        setErrorMessage(error.message()));
1576	                }
1577	            }
1578	        }
1579	        return ControllerResult.of(records, response);
1580	    }
