1590	    ApiError electLeader(String topic, int partitionId, ElectionType electionType,
1591	                         List<ApiMessageAndVersion> records) {
1592	        Uuid topicId = topicsByName.get(topic);
1593	        if (topicId == null) {
1594	            return new ApiError(UNKNOWN_TOPIC_OR_PARTITION,
1595	                "No such topic as " + topic);
1596	        }
1597	        TopicControlInfo topicInfo = topics.get(topicId);
1598	        if (topicInfo == null) {
1599	            return new ApiError(UNKNOWN_TOPIC_OR_PARTITION,
1600	                "No such topic id as " + topicId);
1601	        }
1602	        PartitionRegistration partition = topicInfo.parts.get(partitionId);
1603	        if (partition == null) {
1604	            return new ApiError(UNKNOWN_TOPIC_OR_PARTITION,
1605	                "No such partition as " + topic + "-" + partitionId);
1606	        }
1607	        if ((electionType == ElectionType.PREFERRED && partition.hasPreferredLeader())
1608	            || (electionType == ElectionType.UNCLEAN && partition.hasLeader())) {
1609	            return new ApiError(Errors.ELECTION_NOT_NEEDED);
1610	        }
1611	
1612	        PartitionChangeBuilder.Election election = PartitionChangeBuilder.Election.PREFERRED;
1613	        if (electionType == ElectionType.UNCLEAN) {
1614	            election = PartitionChangeBuilder.Election.UNCLEAN;
1615	        }
1616	        Optional<ApiMessageAndVersion> record = new PartitionChangeBuilder(
1617	            partition,
1618	            topicId,
1619	            partitionId,
1620	            new LeaderAcceptor(clusterControl, partition),
1621	            featureControl.metadataVersionOrThrow(),
1622	            getTopicEffectiveMinIsr(topic),
1623	            featureControl.isElrFeatureEnabled()
1624	        )
1625	            .setElection(election)
1626	            .setDefaultDirProvider(clusterDescriber)
1627	            .build();
1628	        if (record.isEmpty()) {
1629	            if (electionType == ElectionType.PREFERRED) {
1630	                return new ApiError(Errors.PREFERRED_LEADER_NOT_AVAILABLE);
1631	            } else {
1632	                return new ApiError(Errors.ELIGIBLE_LEADERS_NOT_AVAILABLE);
1633	            }
1634	        }
1635	        records.add(record.get());
1636	        return ApiError.NONE;
1637	    }
