1706	    ControllerResult<Boolean> maybeFenceOneStaleBroker() {
1707	        BrokerHeartbeatManager heartbeatManager = clusterControl.heartbeatManager();
1708	        Optional<BrokerIdAndEpoch> idAndEpoch = heartbeatManager.tracker().maybeRemoveExpired();
1709	        if (idAndEpoch.isEmpty()) {
1710	            log.debug("No stale brokers found.");
1711	            return ControllerResult.of(List.of(), false);
1712	        }
1713	        int id = idAndEpoch.get().id();
1714	        long epoch = idAndEpoch.get().epoch();
1715	        if (!clusterControl.brokerRegistrations().containsKey(id)) {
1716	            log.info("Removing heartbeat tracker entry for unknown broker {} at epoch {}.",
1717	                    id, epoch);
1718	            heartbeatManager.remove(id);
1719	            return ControllerResult.of(List.of(), true);
1720	        } else if (clusterControl.brokerRegistrations().get(id).epoch() != epoch) {
1721	            log.info("Removing heartbeat tracker entry for broker {} at previous epoch {}. " +
1722	                "Current epoch is {}", id, epoch,
1723	                clusterControl.brokerRegistrations().get(id).epoch());
1724	            return ControllerResult.of(List.of(), true);
1725	        }
1726	        // Even though multiple brokers can go stale at a time, we will process
1727	        // fencing one at a time so that the effect of fencing each broker is visible
1728	        // to the system prior to processing the next one.
1729	        log.info("Fencing broker {} at epoch {} because its session has timed out.", id, epoch);
1730	        List<ApiMessageAndVersion> records = new ArrayList<>();
1731	        handleBrokerFenced(id, records);
1732	        heartbeatManager.fence(id);
1733	        return ControllerResult.of(records, true);
1734	    }
