1582	    private static ElectionType electionType(byte electionType) {
1583	        try {
1584	            return ElectionType.valueOf(electionType);
1585	        } catch (IllegalArgumentException e) {
1586	            throw new InvalidRequestException("Unknown election type " + (int) electionType);
