1639	    ControllerResult<BrokerHeartbeatReply> processBrokerHeartbeat(
1640	        BrokerHeartbeatRequestData request,
1641	        long registerBrokerRecordOffset
1642	    ) {
1643	        int brokerId = request.brokerId();
1644	        long brokerEpoch = request.brokerEpoch();
1645	        clusterControl.checkBrokerEpoch(brokerId, brokerEpoch);
1646	        BrokerHeartbeatManager heartbeatManager = clusterControl.heartbeatManager();
1647	        BrokerControlStates states = heartbeatManager.calculateNextBrokerState(brokerId,
1648	            request, registerBrokerRecordOffset, () -> brokersToIsrs.hasLeaderships(brokerId));
1649	        List<ApiMessageAndVersion> records = new ArrayList<>();
1650	        if (states.current() != states.next()) {
1651	            switch (states.next()) {
1652	                case FENCED:
1653	                case SHUTDOWN_NOW:
1654	                    handleBrokerFenced(brokerId, records);
1655	                    break;
1656	                case UNFENCED:
1657	                    handleBrokerUnfenced(brokerId, brokerEpoch, records);
1658	                    break;
1659	                case CONTROLLED_SHUTDOWN:
1660	                    handleBrokerInControlledShutdown(brokerId, brokerEpoch, records);
1661	                    break;
1662	            }
1663	        }
1664	        heartbeatManager.touch(brokerId,
1665	            states.next().fenced(),
1666	            request.currentMetadataOffset());
1667	        if (featureControl.metadataVersionOrThrow().isDirectoryAssignmentSupported()) {
1668	            handleDirectoriesOffline(brokerId, brokerEpoch, request.offlineLogDirs(), records);
1669	        }
1670	        boolean isCaughtUp = request.currentMetadataOffset() >= registerBrokerRecordOffset;
1671	        BrokerHeartbeatReply reply = new BrokerHeartbeatReply(isCaughtUp,
1672	                states.next().fenced(),
1673	                states.next().inControlledShutdown(),
1674	                states.next().shouldShutDown());
1675	        return ControllerResult.of(records, reply);
1676	    }
