1689	                clusterControl.brokerRegistrations().get(brokerId).fenced(),
1690	                request.currentMetadataOffset());
1691	        log.error("processExpiredBrokerHeartbeat: controller event queue overloaded. Timed out " +
1692	                "heartbeat from broker {}.", brokerId);
1693	    }
