1336	                leaderRecoveryState == LeaderRecoveryState.RECOVERING) {
1337	            log.info("Rejecting AlterPartition request from node {} for {}-{} because " +
1338	                    "the leader recovery state cannot change from RECOVERED to RECOVERING. {}",
1339	                    brokerId, topic.name, partitionId,
1340	                    logPartitionChangeInfo(partition, partitionData.newIsrWithEpochs()));
1341	
1342	            return INVALID_REQUEST;
1343	        }
