1368	        List<IneligibleReplica> ineligibleReplicas = new ArrayList<>(0);
1369	        for (BrokerState brokerState : brokerStates) {
1370	            int brokerId = brokerState.brokerId();
1371	            BrokerRegistration registration = clusterControl.registration(brokerId);
1372	            if (registration == null) {
1373	                ineligibleReplicas.add(new IneligibleReplica(brokerId, "not registered"));
1374	            } else if (registration.inControlledShutdown()) {
1375	                ineligibleReplicas.add(new IneligibleReplica(brokerId, "shutting down"));
1376	            } else if (registration.fenced()) {
1377	                ineligibleReplicas.add(new IneligibleReplica(brokerId, "fenced"));
1378	            } else if (brokerState.brokerEpoch() != -1 && registration.epoch() != brokerState.brokerEpoch()) {
1379	                // The given broker epoch should match with the broker epoch in the broker registration, except the
1380	                // given broker epoch is -1 which means skipping the broker epoch verification.
1381	                ineligibleReplicas.add(new IneligibleReplica(brokerId,
1382	                    "broker epoch mismatch: requested=" + brokerState.brokerEpoch()
1383	                        + " VS expected=" + registration.epoch()));
1384	            }
1385	        }
1386	        return ineligibleReplicas;
1387	    }
