101	        if (logRollConfigs.contains(name)) {
102	            return logRollConfigs;
103	        } else if (logRollJitterConfigs.contains(name)) {
104	            return logRollJitterConfigs;
105	        } else if (ServerLogConfigs.LOG_FLUSH_INTERVAL_MS_CONFIG.equals(name)) { // KafkaLogConfigs.LOG_FLUSH_SCHEDULER_INTERVAL_MS_CONFIG is used as default
