26	/**
27	 * Holds dynamic configs, including both dynamic-only configs which have no physical manifestation in server.properties and
28	 * can only be set dynamically (i.e., {@link QuotaConfig#brokerQuotaConfigs()}), and dual-mode configs that can be set
29	 * statically or dynamically.
30	 */
31	public class DynamicConfig {
32	
33	    public static class Broker {
34	
35	        private static final ConfigDef BROKER_CONFIGS;
36	        static {
37	            ConfigDef configs = QuotaConfig.brokerQuotaConfigs();
38	            // Filter and define all dynamic configurations
39	            AbstractKafkaConfig.CONFIG_DEF.configKeys().forEach((name, value) -> {
40	                if (DynamicBrokerConfig.ALL_DYNAMIC_CONFIGS.contains(name)) {
41	                    configs.define(value);
42	                }
43	            });
44	            BROKER_CONFIGS = configs;
45	        }
46	
47	        // In order to avoid circular reference, all DynamicBrokerConfig's variables which are initialized by `DynamicConfig.Broker` should be moved to `DynamicConfig.Broker`.
48	        // Otherwise, those variables of DynamicBrokerConfig will see intermediate state of `DynamicConfig.Broker`, because `BROKER_CONFIGS` is created by `DynamicBrokerConfig.ALL_DYNAMIC_CONFIGS`
49	        public static Set<String> nonDynamicProps() {
50	            Set<String> nonDynamicProps = new HashSet<>(AbstractKafkaConfig.CONFIG_DEF.names());
51	            nonDynamicProps.removeAll(BROKER_CONFIGS.names());
52	            return nonDynamicProps;
53	        }
54	
55	        public static Map<String, ConfigDef.ConfigKey> configKeys() {
56	            return BROKER_CONFIGS.configKeys();
57	        }
58	
59	        public static Set<String> names() {
60	            return BROKER_CONFIGS.names();
61	        }
62	
63	        public static Map<String, Object> validate(Properties props) {
64	            // Validate Names
65	            Properties propResolved = DynamicBrokerConfig.resolveVariableConfigs(props);
66	            // ValidateValues
67	            return BROKER_CONFIGS.parse(propResolved);
68	        }
69	    }
70	
71	}
