3043	        Map<String, LogDirDescription> result = new HashMap<>(response.data().results().size());
3044	        for (DescribeLogDirsResponseData.DescribeLogDirsResult logDirResult : response.data().results()) {
3045	            Map<TopicPartition, ReplicaInfo> replicaInfoMap = new HashMap<>();
3046	            for (DescribeLogDirsResponseData.DescribeLogDirsTopic t : logDirResult.topics()) {
3047	                for (DescribeLogDirsResponseData.DescribeLogDirsPartition p : t.partitions()) {
3048	                    replicaInfoMap.put(
3049	                        new TopicPartition(t.name(), p.partitionIndex()),
3050	                        new ReplicaInfo(p.partitionSize(), p.offsetLag(), p.isFutureKey()));
3051	                }
3052	            }
3053	            result.put(logDirResult.logDir(), new LogDirDescription(
3054	                Errors.forCode(logDirResult.errorCode()).exception(),
3055	                replicaInfoMap,
3056	                logDirResult.totalBytes(),
3057	                logDirResult.usableBytes()));
3058	        }
3059	        return result;
3060	    }
